From b1bdaa865736c50be988f7bec51754c03bc08181 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 19:26:20 +0100
Subject: [PATCH] applets/clipboard: add actions for the current item to the
 context menu

The widget's context menu could only clear the history, while each entry
in the popup can invoke an action, show a QR code or be edited. The menu
now offers these for the current clipboard item, opening the popup.

BUG: 415088
---
 applets/clipboard/qml/main.qml                | 53 +++++++++++++++++++
 .../declarative/declarativehistorymodel.cpp   | 15 ++++++
 klipper/declarative/declarativehistorymodel.h |  6 +++
 3 files changed, 74 insertions(+)

diff --git a/applets/clipboard/qml/main.qml b/applets/clipboard/qml/main.qml
index 101b18486a..e3485f72d4 100644
--- a/applets/clipboard/qml/main.qml
+++ b/applets/clipboard/qml/main.qml
@@ -26,6 +26,8 @@ PlasmoidItem {
     readonly property bool clipboardHasPassword: historyModel.sourceModel.clipboardHasPassword
     readonly property bool selectionHasPassword: historyModel.sourceModel.selectionHasPassword
     readonly property bool hasNothingToShow: isClipboardEmpty && !clipboardHasPassword && !selectionHasPassword
+    // HistoryItemType::Text from historyitem.h
+    readonly property int textItemType: 2

     switchWidth: Kirigami.Units.gridUnit * 12
     switchHeight: Kirigami.Units.gridUnit * 12
@@ -62,6 +64,11 @@ PlasmoidItem {
         main.clipboardMenu.clearHistory()
     }

+    function openCurrentItem(page: string): void {
+        openCurrentItemTimer.page = page;
+        openCurrentItemTimer.restart();
+    }
+
     // BUG 520144
     // QTBUG-146886
     readonly property var backAction: Kirigami.Action {
@@ -80,6 +87,29 @@ PlasmoidItem {
     }

     Plasmoid.contextualActions: [
+        PlasmaCore.Action {
+            text: i18n("Invoke Action")
+            icon.name: "system-run"
+            priority: PlasmaCore.Action.LowPriority
+            visible: historyModel.currentHasAction
+            onTriggered: historyModel.invokeAction(historyModel.currentUuid)
+        },
+        PlasmaCore.Action {
+            text: i18n("Show QR Code")
+            icon.name: "view-barcode-qr"
+            priority: PlasmaCore.Action.LowPriority
+            visible: historyModel.currentType === main.textItemType
+            enabled: !main.clipboardMenu?.editing
+            onTriggered: main.openCurrentItem("barcode")
+        },
+        PlasmaCore.Action {
+            text: i18n("Edit Contents…")
+            icon.name: "document-edit"
+            priority: PlasmaCore.Action.LowPriority
+            visible: historyModel.currentType === main.textItemType
+            enabled: !main.clipboardMenu?.editing
+            onTriggered: main.openCurrentItem("edit")
+        },
         PlasmaCore.Action {
             id: clearAction
             text: i18n("Clear History")
@@ -112,6 +142,29 @@ PlasmoidItem {
         Plasmoid.setInternalAction("configure", configureAction);
     }

+    // The panel gets the focus back once the context menu is gone, which
+    // would close the popup again if it was opened right away
+    Timer {
+        id: openCurrentItemTimer
+        property string page
+        interval: 100
+        onTriggered: {
+            main.expanded = true;
+            const menu = main.clipboardMenu;
+            menu.T.StackView.view.popToIndex(0);
+            menu.clearFilter();
+            historyModel.starredOnly = false;
+            const view = menu.view as ListView;
+            view.currentIndex = 0;
+            const item = view.currentItem as Private.ClipboardItemDelegate;
+            if (page === "edit") {
+                item?.edit();
+            } else {
+                item?.barcode();
+            }
+        }
+    }
+
     Private.KlipperInterface {
         id: klipper
     }
diff --git a/klipper/declarative/declarativehistorymodel.cpp b/klipper/declarative/declarativehistorymodel.cpp
index 9c44a5188b..2288db406f 100644
--- a/klipper/declarative/declarativehistorymodel.cpp
+++ b/klipper/declarative/declarativehistorymodel.cpp
@@ -42,6 +42,21 @@ QString DeclarativeHistoryModel::currentText() const
     return m_model->rowCount() == 0 ? QString() : m_model->index(0).data(Qt::DisplayRole).toString();
 }

+QString DeclarativeHistoryModel::currentUuid() const
+{
+    return m_model->rowCount() == 0 ? QString() : m_model->index(0).data(HistoryModel::UuidRole).toString();
+}
+
+int DeclarativeHistoryModel::currentType() const
+{
+    return m_model->rowCount() == 0 ? 0 : m_model->index(0).data(HistoryModel::TypeIntRole).toInt();
+}
+
+bool DeclarativeHistoryModel::currentHasAction() const
+{
+    return m_model->rowCount() != 0 && m_model->index(0).data(HistoryModel::HasActionRole).toBool();
+}
+
 int DeclarativeHistoryModel::sourceCount() const
 {
     return m_model->rowCount();
diff --git a/klipper/declarative/declarativehistorymodel.h b/klipper/declarative/declarativehistorymodel.h
index bd239fbbc8..d989e4606d 100644
--- a/klipper/declarative/declarativehistorymodel.h
+++ b/klipper/declarative/declarativehistorymodel.h
@@ -24,6 +24,9 @@ class DeclarativeHistoryModel : public QSortFilterProxyModel
     Q_PROPERTY(int sourceCount READ sourceCount NOTIFY sourceCountChanged)
     Q_PROPERTY(int starredCount READ starredCount NOTIFY starredCountChanged)
     Q_PROPERTY(QString currentText READ currentText NOTIFY currentTextChanged)
+    Q_PROPERTY(QString currentUuid READ currentUuid NOTIFY currentTextChanged)
+    Q_PROPERTY(int currentType READ currentType NOTIFY currentTextChanged)
+    Q_PROPERTY(bool currentHasAction READ currentHasAction NOTIFY currentTextChanged)

     Q_PROPERTY(bool starredOnly READ starredOnly WRITE setStarredOnly NOTIFY starredOnlyChanged)

@@ -32,6 +35,9 @@ public:
     ~DeclarativeHistoryModel() override;

     QString currentText() const;
+    QString currentUuid() const;
+    int currentType() const;
+    bool currentHasAction() const;
     int sourceCount() const;
     int starredCount() const;

-- 
